// readCounter is a ReadCounter implementation that wraps an io.Reader and
// counts the number of bytes successfully read and the number of Read calls.
type readCounter struct {
	reader io.Reader

	mu   sync.Mutex
	n    int64
	nops int
}

// writeCounter is a WriteCounter implementation that wraps an io.Writer and
// counts the number of bytes successfully written and the number of Write calls.
type writeCounter struct {
	writer io.Writer

	mu   sync.Mutex
	n    int64
	nops int
}

// readWriteCounter is a ReadWriteCounter implementation that wraps an
// io.ReadWriter with a readCounter and a writeCounter.
type readWriteCounter struct {
	*readCounter
	*writeCounter
}

// NewWriteCounter returns a WriteCounter that wraps writer.
func NewWriteCounter(writer io.Writer) WriteCounter {
	return &writeCounter{writer: writer}
}

// NewReadCounter returns a ReadCounter that wraps reader.
func NewReadCounter(reader io.Reader) ReadCounter {
	return &readCounter{reader: reader}
}

// NewReadWriteCounter returns a ReadWriteCounter that wraps readwriter.
func NewReadWriteCounter(readwriter io.ReadWriter) ReadWriteCounter {
	return &readWriteCounter{
		readCounter:  NewReadCounter(readwriter).(*readCounter),
		writeCounter: NewWriteCounter(readwriter).(*writeCounter),
	}
}

// Read reads from the underlying reader, counting the bytes read
// and the number of operations.
func (rc *readCounter) Read(p []byte) (int, error) {
	n, err := rc.reader.Read(p)
	if err != nil {
		return n, err
	}
	rc.mu.Lock()
	rc.n += int64(n)
	rc.nops++
	rc.mu.Unlock()
	return n, err
}

// ReadCount returns the total number of bytes successfully read and
// the total number of Read calls.
func (rc *readCounter) ReadCount() (int64, int) {
	rc.mu.Lock()
	defer rc.mu.Unlock()
	return rc.n, rc.nops
}

// Write writes to the underlying writer, counting the bytes written
// and the number of operations.
func (wc *writeCounter) Write(p []byte) (int, error) {
	n, err := wc.writer.Write(p)
	if err != nil {
		return n, err
	}
	wc.mu.Lock()
	wc.n += int64(n)
	wc.nops++
	wc.mu.Unlock()
	return n, err
}

// WriteCount returns the total number of bytes successfully written and
// the total number of Write calls.
func (wc *writeCounter) WriteCount() (int64, int) {
	wc.mu.Lock()
	defer wc.mu.Unlock()
	return wc.n, wc.nops
