package paasio

import (
	"io"
	"sync"
)

// readCounter is a ReadCounter that wraps an io.Reader and keeps track of
// the total number of bytes successfully read and the number of Read calls.
type readCounter struct {
	reader io.Reader

	mu   sync.Mutex
	n    int64
	nops int
}

// writeCounter is a WriteCounter that wraps an io.Writer and keeps track of
// the total number of bytes successfully written and the number of Write calls.
type writeCounter struct {
	writer io.Writer

	mu   sync.Mutex
	n    int64
	nops int
}

// readWriteCounter is a ReadWriteCounter that combines a readCounter and a
// writeCounter over the same underlying io.ReadWriter.
type readWriteCounter struct {
	*readCounter
	*writeCounter
}

// NewReadCounter returns a ReadCounter that wraps reader.
func NewReadCounter(reader io.Reader) ReadCounter {
	return &readCounter{reader: reader}
}

// NewWriteCounter returns a WriteCounter that wraps writer.
func NewWriteCounter(writer io.Writer) WriteCounter {
	return &writeCounter{writer: writer}
}

// NewReadWriteCounter returns a ReadWriteCounter that wraps readwriter.
func NewReadWriteCounter(readwriter io.ReadWriter) ReadWriteCounter {
	return &readWriteCounter{
		readCounter:  NewReadCounter(readwriter).(*readCounter),
		writeCounter: NewWriteCounter(readwriter).(*writeCounter),
	}
}

// Read reads from the underlying reader, updating the byte and operation
// counts when the read succeeds.
func (rc *readCounter) Read(p []byte) (int, error) {
	n, err := rc.reader.Read(p)
	if err != nil {
		return n, err
	}
	rc.mu.Lock()
	rc.n += int64(n)
	rc.nops++
	rc.mu.Unlock()
	return n, err
}

// ReadCount returns the total number of bytes successfully read along with
// the total number of successful Read calls.
func (rc *readCounter) ReadCount() (int64, int) {
	rc.mu.Lock()
	defer rc.mu.Unlock()
	return rc.n, rc.nops
}

// Write writes to the underlying writer, updating the byte and operation
// counts when the write succeeds.
func (wc *writeCounter) Write(p []byte) (int, error) {
	n, err := wc.writer.Write(p)
	if err != nil {
		return n, err
	}
	wc.mu.Lock()
	wc.n += int64(n)
	wc.nops++
	wc.mu.Unlock()
	return n, err
}

// WriteCount returns the total number of bytes successfully written along
// with the total number of successful Write calls.
func (wc *writeCounter) WriteCount() (int64, int) {
	wc.mu.Lock()
	defer wc.mu.Unlock()
	return wc.n, wc.nops
}
